contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We craft minimal inputs to call fillOrder and then assert a general invariant:
    // For a long call order with a non-weth ERC20 baseAsset (so ETH isn't used),
    // after fillOrder returns (not reverted), the maker owns the token id = uint256(orderHash)
    // and the filler (msg.sender of fillOrder, which will be this contract) owns the opposite position id,
    // and the Ether balance of c does not increase due to the premium transfer (since ERC20 used).

    function run(
        address maker,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce,
        address[] calldata whitelist,
        address[] calldata floorTokens
    ) public payable {
        // Precondition: baseAsset must be a non-zero address and not equal to c.weth(),
        // and ensure duration reasonable to avoid other require checks in fillOrder
        require(baseAsset != address(0), "baseAsset != 0");
        address wethAddr = c.weth();
        require(baseAsset != wethAddr, "use non-weth baseAsset");
        require(duration < 10_000 days, "duration too long");
        require(block.timestamp < expiration, "not expired");

        // Build an Order in memory matching C.Order layout
        C.Order memory order;
        order.maker = maker;
        order.isCall = true;
        order.isLong = true;
        order.baseAsset = baseAsset;
        order.strike = strike;
        order.premium = premium;
        order.duration = duration;
        order.expiration = expiration;
        order.nonce = nonce;
        order.whitelist = whitelist;
        order.floorTokens = floorTokens;

        // empty asset arrays
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);
        order.erc20Assets = erc20Assets;
        order.erc721Assets = erc721Assets;

        // We need a signature argument; for property test we can pass empty bytes and rely on isValidSignatureNow
        // to probably fail; but to make the call proceed we *must* let SignatureChecker accept it.
        // However, we cannot craft a valid signature here. Instead, we will observe whether the call reverts
        // and assert properties conditional on non-revert. So we capture revert status.

        bool reverted;
        bytes memory sig = "";
        uint256[] memory floorIds = new uint256[](floorTokens.length);

        uint256 beforeBalance = address(c).balance;
        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);
        uint256 makerTokenId = uint256(orderHash);
        uint256 fillerTokenId = uint256(oppositeHash);

        try c.fillOrder(order, sig, floorIds) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After the call: if it did NOT revert, then the maker should own token makerTokenId and this contract (the filler)
        // should own fillerTokenId. Also, because we used a non-weth baseAsset, any premium transfer should have been done
        // via ERC20 safeTransferFrom and thus c's ETH balance should remain unchanged.

        // Read owners only if call succeeded; ownerOf will revert if token not minted, so guard with reverted flag.
        bool ownersOk = true;
        if (!reverted) {
            address makerOwner = c.ownerOf(makerTokenId);
            address fillerOwner = c.ownerOf(fillerTokenId);
            // makerOwner must equal order.maker
            // fillerOwner must equal address(this)
            ownersOk = (makerOwner == maker) && (fillerOwner == address(this));
        }

        uint256 afterBalance = address(c).balance;

        // General rule asserted: if fillOrder did not revert, then ownersOk is true and contract ETH balance unchanged
        assert(reverted || (ownersOk && afterBalance == beforeBalance));
    }

    receive() external payable {}
 }

