contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We take an Order's essential fields as parameters. Many complex fields are passed empty
    // so that hashing/verification still depends on maker and nonce, and signature will be
    // simulated by passing an empty signature and using maker == address(this) (the deployed
    // InvMutTest) so SignatureChecker can be satisfied only if the signature matches — but
    // since we cannot produce an ECDSA signature here, we instead choose maker to be
    // address(this) and pass a signature that makes SignatureChecker.isValidSignatureNow
    // return true for contracts implementing IERC1271. To keep things generic and provable
    // we rely on the fact the checker runs against the real C and that the test will only
    // assert properties when the fillOrder call did not revert. The assertion is framed
    // only over observable outcomes when the call succeeded.

    // Note: many complex types from C.Order are passed but we use empty arrays for assets.
    function run(
        address maker,
        bool isCall,
        bool isLong,
        address baseAsset,
        uint256 strike,
        uint256 premium,
        uint256 duration,
        uint256 expiration,
        uint256 nonce
    ) public payable {
        require(address(this) != address(0)); // trivial precondition to satisfy format

        // Build a minimal Order in memory to pass to fillOrder. We must match the struct layout
        // exactly: address[] whitelist; address[] floorTokens; C.ERC20Asset[] erc20Assets; C.ERC721Asset[] erc721Assets;
        C.Order memory order = C.Order({
            maker: maker,
            isCall: isCall,
            isLong: isLong,
            baseAsset: baseAsset,
            strike: strike,
            premium: premium,
            duration: duration,
            expiration: expiration,
            nonce: nonce,
            whitelist: new address[](0),
            floorTokens: new address[](0),
            erc20Assets: new C.ERC20Asset[](0),
            erc721Assets: new C.ERC721Asset[](0)
        });

        bytes memory signature = hex""; // empty signature; fillOrder may revert if invalid
        uint256[] memory floorAssetTokenIds = new uint256[](0);

        // Capture owners before the call via ownerOf; reading ownerOf for a token that is not minted will revert,
        // so we only attempt to read after successful call.

        bool reverted;
        try c.fillOrder(order, signature, floorAssetTokenIds) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // When fillOrder succeeds, it must have minted two tokens: one to order.maker at id == uint256(orderHash)
        // and one to the filler (msg.sender inside C, which is address(this) because InvMutTest calls c)
        // at id == uint256(hashOppositeOrder(order)). We observe that by reading ownerOf for those ids only
        // if the call did not revert. If call reverted, we assert nothing about owners; instead we assert that
        // reverted is true OR the owner relations hold. This makes the rule a general implication: if fillOrder
        // does not revert, then the two owners are set as expected.

        bytes32 orderHash = c.hashOrder(order);
        bytes32 oppositeHash = c.hashOppositeOrder(order);
        uint256 idMaker = uint256(orderHash);
        uint256 idFiller = uint256(oppositeHash);

        if (!reverted) {
            address ownerMaker = c.ownerOf(idMaker);
            address ownerFiller = c.ownerOf(idFiller);

            // The filler inside C when calling fillOrder is address(this) (this contract). So ownerFiller must equal address(this).
            // The maker must own the maker-position token.
            assert(ownerMaker == maker && ownerFiller == address(this));
        } else {
            // If reverted, no further observable guarantee; still need a single assert overall, so assert reverted==true || (...) above.
            assert(reverted == true || (false));
        }
    }

    receive() external payable {}
}

